-- =================================================================
-- SCRIPT DE MIGRACIÓN: INVENTARIO INICIAL SUCURSAL COCHABAMBA (30/09/2026)
-- PRODUCTOS CON STOCK REGISTRADO: 292
-- TOTAL PRODUCTOS CON STOCK > 0: 292
-- TOTAL UNIDADES EN STOCK: 57080
-- =================================================================

BEGIN;

-- 1. Limpiar lotes iniciales previos de Sucursal Cochabamba si existieran
DELETE FROM lotes WHERE "numeroLote" LIKE 'L-INI-CBBA-%' AND "sucursalId" = (SELECT id FROM sucursales WHERE LOWER(nombre) LIKE '%cbba%' LIMIT 1);

-- 2. Actualizar o insertar inventario para productos en Sucursal Cochabamba
-- [BH-P40] Lija en Disco Velcro 7" BH P40 -> Stock: 345
DO $$
DECLARE
    v_prod_id INT;
    v_suc_id INT;
    v_inv_id INT;
BEGIN
    SELECT id INTO v_prod_id FROM productos WHERE codigo = 'BH-P40' LIMIT 1;
    SELECT id INTO v_suc_id FROM sucursales WHERE LOWER(nombre) LIKE '%cbba%' LIMIT 1;

    IF v_prod_id IS NOT NULL AND v_suc_id IS NOT NULL THEN
        SELECT id INTO v_inv_id FROM inventario WHERE "productoId" = v_prod_id AND "sucursalId" = v_suc_id LIMIT 1;

        IF v_inv_id IS NOT NULL THEN
            UPDATE inventario 
            SET "stockActual" = 345, "actualizadoEn" = NOW() 
            WHERE id = v_inv_id;
        ELSE
            INSERT INTO inventario ("productoId", "sucursalId", "stockActual", "stockMinimo", "stockMaximo", "precioCompra", "precioVenta", "creadoEn", "actualizadoEn")
            VALUES (v_prod_id, v_suc_id, 345, 0, 0, COALESCE((SELECT "precioCompra" FROM productos WHERE id = v_prod_id), 0), COALESCE((SELECT "precioVenta" FROM productos WHERE id = v_prod_id), 0), NOW(), NOW());
        END IF;
    END IF;
END $$;

