    v_prod_id INT;
    v_suc_id INT;
    v_inv_id INT;
BEGIN
    SELECT id INTO v_prod_id FROM productos WHERE codigo = 'ZY-TPMC-24' LIMIT 1;
    SELECT id INTO v_suc_id FROM sucursales WHERE LOWER(nombre) LIKE '%cbba%' LIMIT 1;

    IF v_prod_id IS NOT NULL AND v_suc_id IS NOT NULL THEN
        SELECT id INTO v_inv_id FROM inventario WHERE "productoId" = v_prod_id AND "sucursalId" = v_suc_id LIMIT 1;

        IF v_inv_id IS NOT NULL THEN
            UPDATE inventario 
            SET "stockActual" = 3, "actualizadoEn" = NOW() 
            WHERE id = v_inv_id;
        ELSE
            INSERT INTO inventario ("productoId", "sucursalId", "stockActual", "stockMinimo", "stockMaximo", "precioCompra", "precioVenta", "creadoEn", "actualizadoEn")
            VALUES (v_prod_id, v_suc_id, 3, 0, 0, COALESCE((SELECT "precioCompra" FROM productos WHERE id = v_prod_id), 0), COALESCE((SELECT "precioVenta" FROM productos WHERE id = v_prod_id), 0), NOW(), NOW());
        END IF;
    END IF;
END $$;

